# English for recurring Common prayers of the Missale O.P. 1939 (name filled in per Mass)
SE_PRAESTA = "Grant us, we beseech You, almighty God, that the offering of our lowliness may be pleasing to You in honor of Your saints, and may purify us alike in body and mind"
PC_QUAESUMUS = "We beseech You, almighty God, that we who have received the food of heaven may, through the intercession of blessed {n}, Your confessor, be thereby defended against all adversity"
SE_ACCEPTA = "May the offering of Your consecrated people be acceptable to You, O Lord, in honor of Your saints, through whose merits they acknowledge that they have received help in tribulation"
PC_SATIASTI = "You have filled Your household, O Lord, with sacred gifts; ever refresh us, we beseech You, by the intercession of her whose feast we celebrate"
SE_LAUDIS = "We offer You, O Lord, sacrifices of praise in commemoration of Your saints, through whom we trust to be delivered from evils both present and to come"
PC_REFECTI = "Refreshed with heavenly food and drink, O our God, we humbly entreat You that we may also be defended by the prayers of him in whose commemoration we have received these gifts"
SE_ACCEPTA_SIT = "May our devotion be acceptable in Your sight, O Lord, and may it become salutary for us through the pleading of him on whose feast it is offered"
PC_DA = "Grant, we beseech You, O Lord, to Your faithful ever to rejoice in the veneration of Your saints, and to be defended by their unceasing intercession"
